#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumMountainRemovals(vector<int>& nums) {
        int n = nums.size();
        vector<int> lis_left(n, 1);
        vector<int> tails;
        for (int i = 0; i < n; ++i) {
            auto it = lower_bound(tails.begin(), tails.end(), nums[i]);
            int idx = it - tails.begin();
            if (it == tails.end()) tails.push_back(nums[i]);
            else *it = nums[i];
            lis_left[i] = idx + 1;
        }
        vector<int> lis_right(n, 1);
        tails.clear();
        for (int i = n - 1; i >= 0; --i) {
            auto it = lower_bound(tails.begin(), tails.end(), nums[i]);
            int idx = it - tails.begin();
            if (it == tails.end()) tails.push_back(nums[i]);
            else *it = nums[i];
            lis_right[i] = idx + 1;
        }
        int max_mountain = 0;
        for (int i = 1; i < n - 1; ++i) {
            if (lis_left[i] > 1 && lis_right[i] > 1) {
                max_mountain = max(max_mountain, lis_left[i] + lis_right[i] - 1);
            }
        }
        return n - max_mountain;
    }
};

import java.util.*;

class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        int[] lisLeft = new int[n];
        List<Integer> tails = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            int idx = Collections.binarySearch(tails, nums[i]);
            if (idx < 0) idx = -(idx + 1);
            if (idx == tails.size()) tails.add(nums[i]);
            else tails.set(idx, nums[i]);
            lisLeft[i] = idx + 1;
        }
        int[] lisRight = new int[n];
        tails.clear();
        for (int i = n - 1; i >= 0; --i) {
            int idx = Collections.binarySearch(tails, nums[i]);
            if (idx < 0) idx = -(idx + 1);
            if (idx == tails.size()) tails.add(nums[i]);
            else tails.set(idx, nums[i]);
            lisRight[i] = idx + 1;
        }
        int maxMountain = 0;
        for (int i = 1; i < n - 1; ++i) {
            if (lisLeft[i] > 1 && lisRight[i] > 1) {
                maxMountain = Math.max(maxMountain, lisLeft[i] + lisRight[i] - 1);
            }
        }
        return n - maxMountain;
    }
}

