var minimumMountainRemovals = function(nums) {
    const n = nums.length;
    function getLis(arr) {
        const lis = Array(n).fill(1);
        const tails = [];
        for (let i = 0; i < n; ++i) {
            let lo = 0, hi = tails.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (tails[mid] < arr[i]) lo = mid + 1;
                else hi = mid;
            }
            tails[lo] = arr[i];
            lis[i] = lo + 1;
        }
        return lis;
    }
    const lisLeft = getLis(nums);
    const lisRight = getLis(nums.slice().reverse()).reverse();
    let maxMountain = 0;
    for (let i = 1; i < n - 1; ++i) {
        if (lisLeft[i] > 1 && lisRight[i] > 1) {
            maxMountain = Math.max(maxMountain, lisLeft[i] + lisRight[i] - 1);
        }
    }
    return n - maxMountain;
};
